namespace QuickCode.Demo.Portal.Controllers;

/// <summary>
/// Progressive BLOB_* upload for Portal (and clients that talk to Portal directly).
/// Form posts still upload via BaseController on Insert/Update; this endpoint returns a URL early.
/// </summary>
[Authorize]
[Route("Media")]
public class MediaController : Controller
{
    private readonly IBlobImageStorage _storage;

    public MediaController(IBlobImageStorage storage)
    {
        _storage = storage;
    }

    [HttpPost("Upload")]
    [RequestSizeLimit(BlobUploadLimits.RequestBodyBytes)]
    [RequestFormLimits(MultipartBodyLengthLimit = BlobUploadLimits.RequestBodyBytes)]
    public async Task<IActionResult> Upload()
    {
        var file = Request.Form.Files.GetFile("file") ?? Request.Form.Files.FirstOrDefault();
        if (file == null || file.Length <= 0)
        {
            return BadRequest(new { message = "No file was uploaded." });
        }

        if (!BlobUploadLimits.TryValidate(file, out var sizeError))
        {
            return BadRequest(new { message = sizeError });
        }

        try
        {
            await using var stream = new MemoryStream();
            await file.CopyToAsync(stream);
            stream.Position = 0;
            var url = _storage.Upload(stream, file.ContentType ?? "application/octet-stream");
            if (string.IsNullOrWhiteSpace(url))
            {
                return StatusCode(StatusCodes.Status500InternalServerError, new { message = "Upload completed but no URL was returned." });
            }

            return Json(new { url });
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, new { message = ex.Message });
        }
    }
